function CosmicPlanet({ sign, setSign }) { const [index, setIndex] = useState(0); useEffect(() => { const match = PLANET_VARIANTS.findIndex(v => v.signs.includes(sign)); if (match >= 0) setIndex(match); }, [sign]); const cycle = dir => setIndex(current => (current + dir + PLANET_VARIANTS.length) % PLANET_VARIANTS.length); const variant = PLANET_VARIANTS[index]; return <div className="cosmos" aria-label="Cosmic ringed planet" data-testid="cosmic-planet-visual"><div className="planet-halo" aria-hidden="true" /><div className="planet-aura" aria-hidden="true" data-testid="planet-atmosphere-glow" /><div className="cosmic-planet-wrap"><img src={variant.src} alt={`${variant.label} cosmic planet`} className="cosmic-planet-img" draggable="false" data-testid="cosmic-planet-image" /></div><button type="button" className="planet-nav next" onClick={e => { e.preventDefault(); cycle(1); }} aria-label="Cycle planet variant" data-testid="planet-next-button"><ChevronRight size={16} /></button><div className="planet-chip" data-testid="planet-variant-chip"><span>{variant.label}</span><em>{sign}</em></div></div>; }
function StarField({ count = 60, fixed = false }) {
  const stars = useMemo(() => {
    const cols = Math.ceil(Math.sqrt(count * 1.6));
    const rows = Math.ceil(count / cols);
    const cellW = 100 / cols;
    const cellH = 100 / rows;
    return Array.from({ length: count }).map((_, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      const special = Math.random() < 0.22;
      const size = special ? 2.4 + Math.random() * 1.2 : 1.4 + Math.random() * 1.2;
      return {
        id: i,
        left: col * cellW + cellW * 0.12 + Math.random() * cellW * 0.76,
        top: row * cellH + cellH * 0.12 + Math.random() * cellH * 0.76,
        size,
        ray: special ? size * (5 + Math.random() * 2.5) : 0,
        sparkle: special,
        delay: Math.random() * 9,
        duration: 4.5 + Math.random() * 6.5,
        base: 0.32 + Math.random() * 0.18,
        peak: special ? 1 : 0.85 + Math.random() * 0.15,
      };
    });
  }, [count]);
  return <div className={`starfield ${fixed ? "starfield-fixed" : ""}`} aria-hidden="true" data-testid={fixed ? "global-starfield" : "hero-starfield"}>{stars.map(s => (
    <span key={s.id} className={`star-dot ${s.sparkle ? "sparkle" : ""}`} style={{ left: `${s.left}%`, top: `${s.top}%`, width: `${s.size}px`, height: `${s.size}px`, "--dur": `${s.duration}s`, "--delay": `${s.delay}s`, "--base": s.base, "--peak": s.peak, "--ray": `${s.ray}px` }} />
  ))}</div>;
}
