function Horoscope({ sign, onSave, saved }) { const [open, setOpen] = useState(false); const data = ZODIAC_DATA[sign] || ZODIAC_DATA["♌"]; const share = async () => { const text = `${data.name}: ${data.body} Lucky color: ${data.color}. Lucky number: ${data.number}.`; try { if (navigator.share) await navigator.share({ title: "My Astro Live Horoscope", text }); else await navigator.clipboard.writeText(text); toast.success(navigator.share ? "Horoscope shared" : "Horoscope copied to clipboard"); } catch { toast("Sharing cancelled"); } }; const downloadCard = () => { const canvas = document.createElement("canvas"); canvas.width = 1200; canvas.height = 630; const context = canvas.getContext("2d"); const gradient = context.createLinearGradient(0, 0, 1200, 630); gradient.addColorStop(0, "#110b32"); gradient.addColorStop(1, "#551b79"); context.fillStyle = gradient; context.fillRect(0, 0, 1200, 630); context.fillStyle = "#f2c7ff"; context.font = "600 32px Space Grotesk, sans-serif"; context.fillText("ASTRO LIVE", 72, 80); context.font = "92px serif"; context.fillText(sign, 72, 245); context.fillStyle = "#ffffff"; context.font = "600 58px Space Grotesk, sans-serif"; context.fillText(data.name, 215, 210); context.font = "28px DM Sans, sans-serif"; context.fillStyle = "#c6b7dd"; context.fillText(data.body.slice(0, 78), 72, 355); context.fillText(`Lucky color  ${data.color}     Lucky number  ${data.number}`, 72, 425); context.fillStyle = "#d875ef"; context.font = "22px DM Sans, sans-serif"; context.fillText("Your guidance, written in the stars.", 72, 540); const link = document.createElement("a"); link.download = `astro-live-${data.name.toLowerCase()}-horoscope.png`; link.href = canvas.toDataURL("image/png"); link.click(); toast.success("Horoscope image downloaded"); }; return <section className="panel horoscope-panel" data-testid="daily-horoscope-section"><SectionTitle onClick={() => toast("Your full horoscope is coming into focus")} testid="horoscope-view-all">Daily Horoscope</SectionTitle><div className="zodiac-head"><div className="leo-icon" data-testid="horoscope-sign-icon">{sign}</div><div><strong data-testid="horoscope-sign-name">{data.name}</strong><small>{data.dates}</small></div><button onClick={() => setOpen(!open)} data-testid="horoscope-expand-button"><ChevronDown size={16} className={open ? "rotate" : ""} /></button></div><p className="horoscope-copy" data-testid="horoscope-body-text">{data.body}</p>{open && <div className="expanded-note" data-testid="horoscope-expanded-text">{data.extra}</div>}<div className="luck-row"><div><span>Lucky Color</span><strong><i /> {data.color}</strong></div><div><span>Lucky Number</span><strong>{data.number}</strong></div></div><div className="horoscope-actions"><button onClick={onSave} className={saved ? "saved" : ""} data-testid="save-horoscope-button">{saved ? <Check size={14} /> : <Save size={14} />} {saved ? "Saved" : "Save reading"}</button><button onClick={share} data-testid="share-horoscope-button"><Share2 size={14} /> Share card</button><button onClick={downloadCard} data-testid="download-horoscope-image-button"><ArrowRight size={14} /> Image</button></div></section>; }
function pickTheme(data) { const t = `${data.body} ${data.extra} ${data.mood}`.toLowerCase(); if (t.includes("confiden") || t.includes("boss") || t.includes("spotlight")) return "a powerful, glowing, confident scene with radiant light bursting outward"; if (t.includes("love") || t.includes("heart") || t.includes("hint") || t.includes("someone")) return "a romantic, dreamy celestial atmosphere with soft pink and violet light"; if (t.includes("career") || t.includes("focus") || t.includes("work") || t.includes("ambit")) return "an ambitious, energetic, achievement-focused scene with upward light rays"; if (t.includes("quiet") || t.includes("transform") || t.includes("magnetic") || t.includes("let go")) return "a scene of transformation, light breaking through darkness into clarity"; if (t.includes("calm") || t.includes("balance") || t.includes("peace") || t.includes("gentle")) return "a calm, ethereal, beautifully balanced atmosphere with soft glowing symmetry"; return "a magical, premium cosmic scene full of quiet wonder"; }
function buildArtPrompt(data, sign) { const cfg = ZODIAC_ART_CONFIG[sign] || ZODIAC_ART_CONFIG["♌"]; const theme = pickTheme(data); const seed = Math.floor(Math.random() * 1000); return `A premium, Gen-Z astrology Instagram Story artwork (vertical composition, variant #${seed}) starring ${cfg.animal}, set in ${cfg.atmosphere}. The emotional theme of the day: ${theme}. Story: ${data.body} ${data.extra} Glowing ${data.color.toLowerCase()} light accents, the ${data.name} zodiac symbol subtly integrated into the scene, glowing stars and faint constellations in the background, elegant neon rim light, subtle glassmorphism highlights, cinematic dramatic lighting, richly detailed central artwork, visually striking, modern magical aesthetic, no text, no watermark, no logos, no UI elements.`; }
async function generateOneArt(s, n, data) { const prompt = buildArtPrompt(data, s); const response = await fetch(`${API}/horoscope/art`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sign: s, prompt }) }); if (!response.ok) throw new Error("generation failed"); const result = await response.json(); return { url: `${process.env.REACT_APP_BACKEND_URL}${result.image_url}`, prompt }; }
