function CosmicArtPanel({ sign }) { const [artMap, setArtMap] = useState({}); const [generatingSign, setGeneratingSign] = useState(null); const [openSign, setOpenSign] = useState(null); const [errorMap, setErrorMap] = useState({}); const generateFor = async (s, n) => { setGeneratingSign(s); setOpenSign(s); setErrorMap(current => ({ ...current, [s]: null })); try { const data = ZODIAC_DATA[s] || ZODIAC_DATA["♌"]; const { url } = await generateOneArt(s, n, data); setArtMap(current => ({ ...current, [s]: url })); toast.success(`${n} Rasi Palan is ready`); } catch { setErrorMap(current => ({ ...current, [s]: "Cosmic art is taking a short break — the rest of your Rasi Palan is ready below. Try Generate Again shortly." })); toast.error(`Could not generate ${n} art right now`); } finally { setGeneratingSign(null); } }; const handleCardClick = (s, n) => { if (artMap[s]) { setOpenSign(s); return; } generateFor(s, n); }; const openName = openSign ? (ZODIAC_ALL.find(z => z.s === openSign) || {}).n : null; return <section className="panel art-panel art-panel-wide" data-testid="cosmic-art-section"><div className="section-title"><h2><Sparkles size={16} className="art-title-icon" /> Today's Cosmic Vision — All 12 Signs</h2></div><div className="art-strip" data-testid="cosmic-art-strip">{ZODIAC_ALL.map(({ s, n }) => <CosmicArtCard key={s} s={s} n={n} isActive={s === sign} generating={generatingSign === s} hasArt={!!artMap[s]} onGenerate={() => handleCardClick(s, n)} />)}</div>{openSign && <RasiPalanCard sSign={openSign} name={openName} artUrl={artMap[openSign]} generating={generatingSign === openSign} artError={errorMap[openSign]} onClose={() => setOpenSign(null)} onRegenerate={() => generateFor(openSign, openName)} />}</section>; }
