function LiveRoom({ session, onClose }) { const [state, setState] = useState("waiting"); const labels = { waiting: ["You’re on the guest list", "The room opens in a moment. We’ll bring you in as Acharya Dev gets ready."], active: ["You’re live with Acharya Dev", "The cosmic room is open. Your private consultation is now in progress."], ended: ["Session complete", "Your cosmic session has ended. Save the feeling and return whenever you’re ready."] }; return <div className="modal-backdrop" data-testid="live-room-modal"><div className="modal live-room"><button className="modal-close" onClick={onClose} data-testid="close-live-room-button"><X size={18} /></button><div className={`room-stage ${state}`}><div className="room-orbit">♌</div><span className="room-state"><span />{state === "active" ? "LIVE NOW" : state.toUpperCase()}</span></div><div className="room-tabs"><button className={state === "waiting" ? "active" : ""} onClick={() => setState("waiting")} data-testid="room-waiting-state-button"><ClockIcon /> Waiting</button><button className={state === "active" ? "active" : ""} onClick={() => setState("active")} data-testid="room-active-state-button"><Video size={14} /> Active</button><button className={state === "ended" ? "active" : ""} onClick={() => setState("ended")} data-testid="room-ended-state-button"><Check size={14} /> Ended</button></div><div className="eyebrow">{session?.title || "LIVE SESSION"}</div><h2>{labels[state][0]}</h2><p>{labels[state][1]}</p>{state === "waiting" && <button className="primary-button" onClick={() => setState("active")} data-testid="enter-live-room-button">Enter when ready <ArrowRight size={16} /></button>}{state === "active" && <button className="primary-button" onClick={() => setState("ended")} data-testid="end-live-room-button">End session <X size={16} /></button>}{state === "ended" && <button className="primary-button" onClick={onClose} data-testid="close-ended-room-button">Return to dashboard <ArrowRight size={16} /></button>}</div></div>; }
function ConsultationModal({ name, onClose, onSave }) { return <div className="modal-backdrop" data-testid="consultation-modal"><div className="modal"><button className="modal-close" onClick={onClose} data-testid="close-modal-button"><X size={18} /></button><div className="modal-icon"><Sparkles size={22} /></div><div className="eyebrow">PRIVATE CONSULTATION</div><h2>Connect with {name}</h2><p>Your cosmic guide will be with you shortly. This demo consultation is ready to begin.</p><button className="primary-button" onClick={() => { onSave(name); toast.success("Reading saved to your library"); onClose(); }} data-testid="modal-save-reading-button"><Bookmark size={16} /> Save reading</button></div></div>; }
function ClockIcon() { return <span className="clock-icon">◷</span>; }
function SavedReadings({ readings, onBack }) { return <section className="saved-view" data-testid="saved-readings-view"><div className="saved-heading"><div><div className="eyebrow">YOUR COSMIC LIBRARY</div><h1>Saved Readings</h1><p>Keep the insights that feel like they were written for you.</p></div><button className="primary-button" onClick={onBack} data-testid="saved-back-button">Back home <ArrowRight size={16} /></button></div>{readings.length ? <div className="reading-grid">{readings.map(reading => <article className="reading-card" key={reading.id} data-testid={`saved-reading-${reading.id}`}><div className="reading-symbol">♌</div><div><span>LEO · {reading.created_at ? new Date(reading.created_at).toLocaleDateString() : "TODAY"}</span><h3>{reading.title}</h3><p>{reading.content}</p><small>Lucky {reading.lucky_color} · Number {reading.lucky_number}</small></div></article>)}</div> : <div className="empty-reading" data-testid="saved-readings-empty"><Bookmark size={28} /><h2>Your library is ready</h2><p>Save a horoscope or consultation to see it here.</p><button className="primary-button" onClick={onBack} data-testid="empty-readings-back-button">Explore today&apos;s reading <ArrowRight size={16} /></button></div>}</section>; }
