function GlobalStarField() { return <StarField count={70} fixed />; }
function hashString(str) { let hash = 0; for (let i = 0; i < str.length; i++) { hash = (hash << 5) - hash + str.charCodeAt(i); hash |= 0; } return Math.abs(hash); }
const ASTRO_CUE_OUTCOMES = [{ tone: "positive", verdict: "Go for it!", note: "The stars are in your favor today.", bestTime: "10:30 AM – 12:30 PM", energyLabel: "High", energy: 80, good: ["New beginnings", "Meetings", "Learning", "Travel"], careful: ["Arguments", "Impulsive spending", "Overthinking"], why: "Today's planetary energy supports confidence, communication and taking meaningful steps forward." }, { tone: "neutral", verdict: "Good time, stay mindful", note: "Solid energy today — just pace yourself.", bestTime: "2:00 PM – 4:00 PM", energyLabel: "Moderate", energy: 60, good: ["Planning", "Conversations", "Small decisions"], careful: ["Rushing", "Money talks", "Multitasking"], why: "The Moon's steady influence favors thoughtful action over impulsive moves right now." }, { tone: "caution", verdict: "Wait a little", note: "Timing could be better — give it a beat.", bestTime: "6:00 PM – 8:00 PM", energyLabel: "Low", energy: 35, good: ["Reflection", "Rest", "Journaling"], careful: ["Big decisions", "Confrontation", "New commitments"], why: "Mercury's current position favors patience over pushing forward right now." }];
function AstroCue({ sign }) { const [open, setOpen] = useState(false); const [query, setQuery] = useState(""); const [loading, setLoading] = useState(false); const [result, setResult] = useState(null); const today = new Date().toLocaleDateString("en-US", { day: "2-digit", month: "short", year: "numeric" }); const toggleOpen = () => { setOpen(current => !current); }; const getCue = () => { if (!query.trim()) { toast("Type what you're about to do first"); return; } setLoading(true); setResult(null); setTimeout(() => { setResult(ASTRO_CUE_OUTCOMES[hashString(query + sign) % ASTRO_CUE_OUTCOMES.length]); setLoading(false); }, 850); }; const shareCue = async () => { if (!result) return; const text = `Astro Cue — ${result.verdict}: ${result.note}`; try { if (navigator.share) await navigator.share({ title: "My Astro Cue", text }); else await navigator.clipboard.writeText(text); toast.success(navigator.share ? "Cue shared" : "Cue copied to clipboard"); } catch { toast("Sharing cancelled"); } }; return <>
  <button type="button" className={`astro-cue-fab ${open ? "astro-cue-fab-open" : ""}`} onClick={toggleOpen} title="Astro Cue" aria-label="Open Astro Cue" data-testid="astro-cue-fab"><Sparkles size={16} /><span className="astro-cue-fab-label">Astro Cue</span></button>
  {open && <div className="astro-cue-panel" data-testid="astro-cue-panel">
    <div className="astro-cue-head"><div className="astro-cue-head-icon"><Sparkles size={18} /></div><div><strong>Astro Cue</strong><small>Your quick cosmic guidance</small></div><button className="astro-cue-close" onClick={() => setOpen(false)} aria-label="Close Astro Cue" data-testid="astro-cue-close-button"><X size={16} /></button></div>
    <label className="astro-cue-label" htmlFor="astro-cue-input">What are you about to do?</label>
    <div className="astro-cue-input-wrap"><input id="astro-cue-input" type="text" placeholder="Type or speak..." value={query} onChange={e => setQuery(e.target.value)} onKeyDown={e => { if (e.key === "Enter") getCue(); }} data-testid="astro-cue-input" /><button type="button" className="astro-cue-mic" onClick={() => toast("Voice input coming soon")} aria-label="Speak your question" data-testid="astro-cue-mic-button"><Mic size={15} /></button></div>
    <button type="button" className="astro-cue-submit" onClick={getCue} disabled={loading} data-testid="astro-cue-submit-button"><Sparkles size={14} /> {loading ? "Reading the stars..." : "Get My Cue"}</button>
    {(loading || result) && <div className="astro-cue-result" data-testid="astro-cue-result">
      <div className="astro-cue-result-head"><span>TODAY'S CUE</span><small>{today}</small></div>
      {loading ? <div className="astro-cue-loading"><Sparkles size={16} /> Reading today&apos;s alignment...</div> : <>
        <div className={`astro-cue-verdict astro-cue-tone-${result.tone}`}><span className="astro-cue-verdict-icon"><Sparkles size={16} /></span><div><strong>{result.verdict}</strong><p>{result.note}</p></div></div>
        <div className="astro-cue-meta">
          <div className="astro-cue-meta-item"><span className="astro-cue-meta-icon astro-cue-icon-time"><Clock size={14} /></span><div><span>Best Time</span><strong>{result.bestTime}</strong></div></div>
          <div className="astro-cue-meta-item"><span className="astro-cue-meta-icon astro-cue-icon-energy"><Zap size={14} /></span><div><span>Energy</span><strong>{result.energyLabel} · {result.energy}%</strong><div className="astro-cue-energy-bar"><i style={{ width: `${result.energy}%` }} /></div></div></div>
        </div>
        <div className="astro-cue-columns">
          <div className="astro-cue-good"><span className="astro-cue-col-head"><i className="astro-cue-dot astro-cue-dot-good"><Check size={11} /></i> Good For</span><ul>{result.good.map(item => <li key={item}>{item}</li>)}</ul></div>
          <div className="astro-cue-careful"><span className="astro-cue-col-head"><i className="astro-cue-dot astro-cue-dot-careful"><AlertTriangle size={11} /></i> Be Careful With</span><ul>{result.careful.map(item => <li key={item}>{item}</li>)}</ul></div>
        </div>
        <div className="astro-cue-why"><div className="astro-cue-why-head"><span className="astro-cue-why-icon"><Compass size={13} /></span><span className="astro-cue-why-label">Why today?</span></div><p>{result.why}</p></div>
        <div className="astro-cue-footer"><button type="button" onClick={shareCue} data-testid="astro-cue-share-button"><Share2 size={13} /> Share</button><button type="button" onClick={() => toast("Opening your full horoscope")} data-testid="astro-cue-view-horoscope-button">View Full Horoscope <ArrowRight size={13} /></button></div>
      </>}
    </div>}
  </div>}
</>; }
