function LiveChatCard() { const [message, setMessage] = useState(""); const send = () => { if (!message.trim()) return; toast.success("Message sent to live chat"); setMessage(""); }; return <div className="live-chat-card" data-testid="live-chat-card"><div className="live-chat-head"><h3><Sparkles size={14} /> Live Chat</h3><div className="live-chat-online"><span />1.8K Online</div><button className="live-chat-menu" aria-label="More options" data-testid="live-chat-menu-button"><MoreVertical size={16} /></button></div><div className="live-chat-messages" data-testid="live-chat-messages">{LIVE_CHAT_MESSAGES.map((m, i) => <div key={i} className={`live-chat-msg ${m.host ? "live-chat-msg-host" : ""}`}><img src={m.avatar} alt={m.name} /><div><span className="live-chat-msg-head">{m.name} <small>{m.time}</small>{m.host && <em>Host</em>}</span><p>{m.text}</p></div></div>)}</div><div className="live-chat-input"><input value={message} onChange={e => setMessage(e.target.value)} onKeyDown={e => { if (e.key === "Enter") send(); }} placeholder="Type your message..." data-testid="live-chat-input" /><button onClick={send} aria-label="Send message" data-testid="live-chat-send-button"><Send size={15} /></button></div></div>; }
