function LivePage() { return <><LiveHeroHeader /><div className="live-main-grid"><LiveStreamCard /><LiveChatCard /></div><div className="live-secondary-grid"><AskAstrologerCard /><LivePollCard /><LiveEnergyCard /></div><UpcomingLiveSessions /><LiveCommunityCTA /></>; }
function HoroWheel({ sign, setSign }) {
  return (
    <div className="horo-wheel" data-testid="horoscope-wheel">
      <div className="horo-wheel-halo" aria-hidden="true" />
      <div className="horo-wheel-rings" aria-hidden="true">
        <span className="horo-wheel-ring r1" />
        <span className="horo-wheel-ring r2" />
        <span className="horo-wheel-ring r3" />
      </div>
      <div className="horo-wheel-sun" aria-hidden="true">
        <span className="horo-wheel-sun-rays" />
        <span className="horo-wheel-sun-core"><Sparkles size={20} /></span>
      </div>
      <Sparkles size={14} className="horo-wheel-star a" />
      <Sparkles size={10} className="horo-wheel-star b" />
      <Sparkles size={12} className="horo-wheel-star c" />
      {ZODIAC_ALL.map(({ s, n }, i) => {
        const angle = (i * 360) / ZODIAC_ALL.length - 90;
        const rad = (angle * Math.PI) / 180;
        const x = 50 + 43 * Math.cos(rad);
        const y = 50 + 43 * Math.sin(rad);
        return (
          <button key={s} type="button" className={`horo-wheel-sign ${sign === s ? "active" : ""}`} style={{ left: `${x}%`, top: `${y}%` }} onClick={() => setSign(s)} aria-label={n} data-testid={`horoscope-wheel-${n.toLowerCase()}-button`}>
            {s}
          </button>
        );
      })}
    </div>
  );
}
function HoroWheelMini({ sign, setSign }) {
  return (
    <div className="horo-mini-wheel" data-testid="horoscope-mini-wheel">
      <div className="horo-mini-wheel-rings" aria-hidden="true">
        <span className="horo-mini-ring r1" />
        <span className="horo-mini-ring r2" />
      </div>
      <div className="horo-mini-wheel-core">{sign}</div>
      {ZODIAC_ALL.map(({ s, n }, i) => {
        const angle = (i * 360) / ZODIAC_ALL.length - 90;
        const rad = (angle * Math.PI) / 180;
        const x = 50 + 41 * Math.cos(rad);
        const y = 50 + 41 * Math.sin(rad);
        return (
          <button key={s} type="button" className={`horo-mini-sign ${sign === s ? "active" : ""}`} style={{ left: `${x}%`, top: `${y}%` }} onClick={() => setSign(s)} aria-label={n} data-testid={`horoscope-mini-${n.toLowerCase()}-button`}>
            {s}
          </button>
        );
      })}
    </div>
  );
}
